async () => { /* N1 one column, no horizontal scroll, every control reachable within the overlay */ const mg = window.MinigameFramework.currentMinigame; const c = mg.container;
  const cards = [...c.querySelectorAll('[data-suspect]')]; const lefts = new Set(cards.map(e => Math.round(e.getBoundingClientRect().left)));
  const noHScroll = document.documentElement.scrollWidth <= window.innerWidth && c.scrollWidth <= c.clientWidth + 1;
  const ctrls = [...c.querySelectorAll('button, select, [tabindex="0"]')]; const inside = ctrls.every(e => { const r = e.getBoundingClientRect(); return r.left >= 0 && r.right <= window.innerWidth; });
  return window.innerWidth <= 600 && cards.length === 4 && lefts.size === 1 && noHScroll && inside; }
